#include <cstdint>
#include "address.h"
#include "modules.h"

struct gen_aggressive_offset_s1 : public champsim::modules::prefetcher {
    using prefetcher::prefetcher;

    static constexpr uint32_t REGION_SIZE = 512;
    static constexpr uint32_t MAX_OFFSET = 4;
    static constexpr uint32_t MAX_CONFIDENCE = 3;
    static constexpr uint32_t LOW_CONFIDENCE_THRESHOLD = 1;

    struct region_entry {
        uint32_t confidence;
        uint32_t last_offset;
    };

    region_entry regions[1 << 14] = {};

    uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                     uint8_t cache_hit, bool useful_prefetch,
                                     access_type type, uint32_t metadata_in) {
        champsim::address region_addr = addr >> LOG2_BLOCK_SIZE;
        region_addr &= ~((REGION_SIZE >> LOG2_BLOCK_SIZE) - 1);

        uint32_t region_id = (region_addr >> LOG2_BLOCK_SIZE) & ((1 << 14) - 1);
        uint32_t offset = (addr >> LOG2_BLOCK_SIZE) & ((REGION_SIZE >> LOG2_BLOCK_SIZE) - 1);

        if (regions[region_id].confidence > LOW_CONFIDENCE_THRESHOLD) {
            for (uint32_t delta = 1; delta <= MAX_OFFSET; ++delta) {
                uint32_t prefetch_offset = (offset + delta) & ((REGION_SIZE >> LOG2_BLOCK_SIZE) - 1);
                champsim::address prefetch_addr = (region_addr | prefetch_offset) << LOG2_BLOCK_SIZE;
                prefetch_line(ip, prefetch_addr, true, 0);
            }
        }

        regions[region_id].last_offset = offset;
        if (offset == regions[region_id].last_offset + 1) {
            if (regions[region_id].confidence < MAX_CONFIDENCE)
                regions[region_id].confidence++;
        } else {
            if (regions[region_id].confidence > 0)
                regions[region_id].confidence--;
        }

        return metadata_in;
    }

    uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                  uint8_t prefetch, champsim::address evicted_addr,
                                  uint32_t metadata_in) {
        return metadata_in;
    }
};

